'use strict';

process.env.ZN_STATS = 'off';

// audit RF30-3: the download-and-run (pipe_to_shell), startup-file download (rc_download), persistence and egress
// rules against alternate spellings of the same command (quoting, variables, line continuation, braces, globs,
// substitution, wrappers). One shared corpus, test/fixtures/rule_spellings_corpus.json, generated by
// test/fixtures/rule_spellings_gen.py; the Python policy runs the same file (packages/zn-gate-py/tests/test_rule_spellings_corpus.py).
// `expect` is what a POSIX shell really does with the text. Cases the rules do not catch yet are listed in KNOWN_GAPS
// and run as todo: they stay visible, they do not fail the suite, and a fix shows up as a todo that passes.
// Only fake example.com URLs, fake paths and generated fake keys.
// ZN_CORPUS_REPORT=<file.json> writes the verdict of every case (id -> verdict) for the audit table.

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const os = require('os');
const path = require('path');

const { checkCommand } = require('../lib/destructive');
const adapter = require('../lib/agents/claude-code');
const runner = require('../lib/hooks/runner');
const realEngine = require('../lib/scrub/engine');
const { createFakeVault } = require('./helpers/fake_vault');
const { generateAll } = require('./fixtures/fake_secrets');

const CASES = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', 'rule_spellings_corpus.json'), 'utf8'));
const GHP = generateAll(8360, { perType: 1, piiPerType: 1 }).secrets.find((s) => s.type === 'github_pat_classic').value;

// Case ids that a shell runs as the dangerous command (or that must ask) and the rules still allow: audit RF30-3.
const KNOWN_GAPS = new Set([
  'egress-dotenv-001', 'egress-dotenv-002', 'egress-dotenv-003', 'egress-dotenv-004',
  'egress-file-009', 'egress-prog-006', 'egress-prog-008', 'egress-prog-010',
  'egress-prog-011', 'egress-prog-026', 'egress-prog-027', 'egress-prog-028',
  'egress-prog-030', 'egress-prog-038', 'egress-prog-040', 'pts-prog-008',
  'pts-prog-010', 'pts-prog-011', 'pts-prog-025', 'pts-prog-026',
  'pts-prog-027', 'pts-prog-028', 'pts-prog-029', 'pts-prog-030',
  'pts-shell-010', 'pts-shell-020', 'pts-shell-021', 'pts-shell-022',
  'pts-shell-035', 'pts-shell-036', 'pts-shell-040', 'pts-subst-010',
  'pts-subst-011', 'pts-subst-012', 'pts-subst-013', 'pts-subst-014',
  'pts-subst-015', 'pts-subst-016', 'pts-subst-017', 'pts-subst-018',
  'pts-subst-019', 'pts-subst-020', 'pts-subst-021', 'pts-subst-022',
  'pts-subst-023', 'pts-subst-024', 'pts-subst-025', 'pts-subst-028',
  'pts-subst-029', 'pts-subst-031', 'rc-prog-008', 'rc-prog-010',
  'rc-prog-011', 'rc-prog-025', 'rc-prog-026', 'rc-target-011',
  'rc-target-012', 'rc-target-025', 'rc-target-026', 'rc-target-027',
  'rc-target-029', 'rc-target-037', 'rc-target-044', 'rc-target-047',
  'rc-target-048', 'rc-target-049', 'rc-target-050', 'rc-target-051',
]);

const REPORT = {};

async function verdictOf(c) {
  if (c.kind === 'egress') {
    const cmd = c.cmd.split('{{GHP}}').join(GHP);
    let cwd = process.cwd();
    if (c.family === 'egress-dotenv') {
      cwd = fs.mkdtempSync(path.join(os.tmpdir(), 'zn-rf303-'));
      fs.writeFileSync(path.join(cwd, '.env'), 'API_KEY=' + GHP + '\nDB_PASSWORD=example-password-1\n');
    }
    const event = { session_id: 'rf303', cwd, permission_mode: 'default', hook_event_name: 'PreToolUse', tool_name: 'Bash', tool_input: { command: cmd }, tool_use_id: 'toolu_rf303' };
    const res = await runner.handle(adapter, event, { engine: realEngine, vault: createFakeVault(), failMode: 'open' });
    if (cwd !== process.cwd()) fs.rmSync(cwd, { recursive: true, force: true });
    const out = res.output && res.output.hookSpecificOutput;
    const d = out ? out.permissionDecision : 'none';
    return d === 'none' || d === 'allow' ? 'allow' : d;
  }
  const r = checkCommand(c.cmd);
  return r.verdict === 'block' ? 'block:' + String(r.rule).replace('destructive:', '') : 'allow';
}

function matches(c, v) {
  if (c.expect === 'either') return true;
  if (c.expect === 'allow') return v === 'allow';
  if (c.expect === 'block') return v.startsWith('block');
  return v === 'ask' || v === 'deny';
}

for (const c of CASES) {
  const name = c.id + ' ' + c.spelling + ' :: ' + JSON.stringify(c.cmd).slice(0, 90);
  const opts = KNOWN_GAPS.has(c.id) ? { todo: 'audit RF30-3: allowed but a shell runs the dangerous command' } : {};
  test(name, opts, async () => {
    const v = await verdictOf(c);
    REPORT[c.id] = v;
    assert.ok(matches(c, v), c.id + ' expected ' + c.expect + ', got ' + v + ': ' + JSON.stringify(c.cmd));
  });
}

test.after(() => {
  if (process.env.ZN_CORPUS_REPORT) fs.writeFileSync(process.env.ZN_CORPUS_REPORT, JSON.stringify(REPORT, null, 1));
});
